<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import type {TrimapMatteReport} from '../shared/trimap-matte'
import type {EditAction} from '../shared/contracts'
import {useI18n} from './i18n'
const {t,tm}=useI18n()
type Stroke={value:0|128|255;size:number;points:[number,number][]}
type Action=Extract<EditAction,{type:'selection.refine_edges'}>
type Source={width:number;height:number;sourceURL:string;coverageURL:string;coarseSource:'selection'|'mask';previewWidth:number;previewHeight:number}
type Preview=Source&{requestId:number;trimapURL:string;report:TrimapMatteReport}
const props=defineProps<{request:{sessionId:string;documentId:string;expectedRevision:number;idempotencyKey:string};layerId:string}>()
const emit=defineEmits<{cancel:[];applied:[];applying:[active:boolean]}>()
const stage=ref<HTMLDivElement>(),fitWidth=ref(500),canvas=ref<HTMLCanvasElement>(),source=ref<Source>(),preview=ref<Preview>(),loading=ref(true),pending=ref(false),applying=ref(false),problem=ref(''),strokes=ref<Stroke[]>([])
const brush=ref<0|128|255>(128),size=ref(20),boundaryRadius=ref(8),sampleRadius=ref(16),guidedRadius=ref(2),output=ref<Action['output']>('selection'),background=ref('source'),showConstraints=ref(true),scale=ref(1),regionEnabled=ref(false),roi=ref({x:0,y:0,width:1,height:1})
let generation=0,closed=false,sourceImage:HTMLImageElement|undefined,coverageImage:HTMLImageElement|undefined,trimapImage:HTMLImageElement|undefined,resizeObserver:ResizeObserver|undefined
let applySettled:Promise<void>|undefined
let gesture:{pointerId:number;target:HTMLCanvasElement;stroke:Stroke}|undefined
const revision=ref(0),previewRevision=ref(-1),canApply=computed(()=>!!preview.value&&previewRevision.value===revision.value&&!pending.value&&!applying.value&&!gesture),busy=computed(()=>loading.value||applying.value)
function action():Action{return {type:'selection.refine_edges',layerId:props.layerId,output:output.value,boundaryRadius:boundaryRadius.value,sampleRadius:sampleRadius.value,guidedRadius:guidedRadius.value,strokes:strokes.value.map(s=>({...s,points:s.points.map(p=>[...p] as [number,number])})),...(regionEnabled.value?{region:[roi.value.x,roi.value.y,roi.value.width,roi.value.height] as [number,number,number,number]}:{})}}
async function rpc<T>(method:string,params:unknown):Promise<T>{const result=await window.compositor.request<T>(method,params);if(!result.ok)throw Error(`${result.error.code}: ${result.error.message}`);return result.value}
async function cancelJob():Promise<void>{await window.compositor.request('cancelEdgeRefinement',{sessionId:props.request.sessionId}).catch(()=>{})}
function invalidate():void{generation++;revision.value++;preview.value=undefined;previewRevision.value=-1;pending.value=false;coverageImage=undefined;trimapImage=undefined;problem.value='';cancelJob();void restoreCoverage();}
async function image(url:string):Promise<HTMLImageElement>{const img=new Image();img.src=url;await img.decode();return img}
async function restoreCoverage():Promise<void>{const ticket=generation;if(!source.value)return;try{const img=await image(source.value.coverageURL);if(!closed&&ticket===generation){coverageImage=img;draw()}}catch(cause){if(!closed&&ticket===generation)problem.value=String(cause)}}
function draw():void{const c=canvas.value,s=source.value;if(!c||!s||!sourceImage)return;const ctx=c.getContext('2d');if(!ctx)return;const w=s.previewWidth,h=s.previewHeight;if(c.width!==w)c.width=w;if(c.height!==h)c.height=h;ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,w,h);ctx.drawImage(sourceImage,0,0,w,h)
 if(background.value!=='source'&&coverageImage){const mask=document.createElement('canvas');mask.width=w;mask.height=h;const m=mask.getContext('2d')!;m.drawImage(coverageImage,0,0,w,h);const pixels=m.getImageData(0,0,w,h);for(let i=0;i<pixels.data.length;i+=4)pixels.data[i+3]=pixels.data[i+3]<255?pixels.data[i+3]:pixels.data[i];m.putImageData(pixels,0,0);ctx.globalCompositeOperation='destination-in';ctx.drawImage(mask,0,0);ctx.globalCompositeOperation='source-over'}
 if(showConstraints.value){ctx.globalAlpha=.3;if(trimapImage){const overlay=document.createElement('canvas');overlay.width=w;overlay.height=h;const o=overlay.getContext('2d')!;o.drawImage(trimapImage,0,0);const pixels=o.getImageData(0,0,w,h);for(let i=0;i<pixels.data.length;i+=4){const v=pixels.data[i];pixels.data[i]=v===0?255:v===128?255:0;pixels.data[i+1]=v===255?220:v===128?200:20;pixels.data[i+2]=v===255?255:20;pixels.data[i+3]=v===128?180:40}o.putImageData(pixels,0,0);ctx.drawImage(overlay,0,0)}ctx.scale(w/s.width,h/s.height);for(const stroke of [...strokes.value,...(gesture?[gesture.stroke]:[])]){ctx.strokeStyle=ctx.fillStyle=stroke.value===255?'#00dcff':stroke.value===0?'#ff3020':'#ffce00';ctx.lineWidth=stroke.size;ctx.lineCap=ctx.lineJoin='round';ctx.beginPath();const first=stroke.points[0];if(!first)continue;ctx.moveTo(...first);for(const p of stroke.points.slice(1))ctx.lineTo(...p);ctx.stroke();ctx.beginPath();ctx.arc(...first,stroke.size/2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}}
function point(event:PointerEvent):[number,number]{const c=canvas.value!,box=c.getBoundingClientRect(),s=source.value!;return [Math.min(s.width-1,Math.max(0,(event.clientX-box.left)*s.width/box.width)),Math.min(s.height-1,Math.max(0,(event.clientY-box.top)*s.height/box.height))]}
function down(event:PointerEvent):void{if(event.button!==0||busy.value||!source.value||gesture)return;if(strokes.value.length>=256){problem.value=t('Constraint budget reached. Clear or undo constraints.');return}if(!Number.isFinite(size.value)||size.value<1||size.value>512){problem.value=t('Choose a constraint size from 1 to 512 pixels.');return}event.preventDefault();invalidate();gesture={pointerId:event.pointerId,target:event.currentTarget as HTMLCanvasElement,stroke:{value:brush.value,size:size.value,points:[point(event)]}};gesture.target.setPointerCapture(event.pointerId);draw()}
function move(event:PointerEvent):void{if(!gesture||event.pointerId!==gesture.pointerId)return;event.preventDefault();const p=point(event),last=gesture.stroke.points.at(-1)!;if(Math.hypot(p[0]-last[0],p[1]-last[1])<.5)return;if(gesture.stroke.points.length+strokes.value.reduce((n,s)=>n+s.points.length,0)>=10000){finish(true);problem.value=t('Constraint stroke is too long. Use shorter strokes.');return}gesture.stroke.points.push(p);draw()}
function finish(cancel=false):void{const g=gesture;if(!g)return;gesture=undefined;if(g.target.hasPointerCapture(g.pointerId))g.target.releasePointerCapture(g.pointerId);if(!cancel)strokes.value.push(g.stroke);draw()}
function up(event:PointerEvent):void{if(gesture?.pointerId!==event.pointerId)return;move(event);finish()}
function cancelPointer(event:PointerEvent):void{if(gesture?.pointerId===event.pointerId)finish(true)}
function key(event:KeyboardEvent):void{if(event.key!=='Escape')return;event.preventDefault();event.stopPropagation();if(gesture)finish(true);else close()}
async function close():Promise<void>{if(closed)return;if(applying.value){await window.compositor.request('cancelImageOperation',{sessionId:props.request.sessionId}).catch(()=>{});await applySettled;if(closed)return}closed=true;generation++;finish(true);cancelJob();emit('cancel')}
function measure():void{const s=source.value,box=stage.value;if(s&&box)fitWidth.value=Math.max(1,Math.min(box.clientWidth,box.clientHeight*s.width/s.height))}
function fit():void{scale.value=1;measure()}
const stageStyle=computed(()=>({background:background.value==='black'?'#000':background.value==='white'?'#fff':background.value==='gray'?'#808080':undefined}))
async function makePreview():Promise<void>{if(!source.value||busy.value||gesture)return;const ticket=++generation,atRevision=revision.value;preview.value=undefined;previewRevision.value=-1;pending.value=true;problem.value='';try{await cancelJob();if(closed||ticket!==generation)return;const result=await rpc<Preview>('edgeRefinementPreview',{request:{...props.request,action:action()},requestId:ticket});if(closed||ticket!==generation)return;const [coverage,trimap]=await Promise.all([image(result.coverageURL),image(result.trimapURL)]);if(closed||ticket!==generation)return;preview.value=result;coverageImage=coverage;trimapImage=trimap;previewRevision.value=atRevision;draw()}catch(cause){if(!closed&&ticket===generation)problem.value=cause instanceof Error?cause.message:String(cause)}finally{if(!closed&&ticket===generation)pending.value=false}}
async function apply():Promise<void>{if(!canApply.value)return;applying.value=true;emit('applying',true);problem.value='';applySettled=(async()=>{try{await rpc('apply',{...props.request,action:action()});if(closed)return;closed=true;generation++;cancelJob();emit('applied')}catch(cause){if(!closed)problem.value=cause instanceof Error?cause.message:String(cause)}finally{applying.value=false;emit('applying',false)}})();await applySettled}
watch([boundaryRadius,sampleRadius,guidedRadius,output,regionEnabled,()=>roi.value.x,()=>roi.value.y,()=>roi.value.width,()=>roi.value.height],invalidate)
watch([background,showConstraints],draw)
onMounted(async()=>{window.addEventListener('blur',blur);try{const initial=await rpc<Source>('edgeRefinementSource',{request:{...props.request,action:action()}});if(closed)return;source.value=initial;roi.value={x:0,y:0,width:initial.width,height:initial.height};const [src,coverage]=await Promise.all([image(initial.sourceURL),image(initial.coverageURL)]);if(closed)return;sourceImage=src;coverageImage=coverage;await nextTick();draw();canvas.value?.focus();measure();resizeObserver=new ResizeObserver(measure);if(stage.value)resizeObserver.observe(stage.value)}catch(cause){if(!closed)problem.value=cause instanceof Error?cause.message:String(cause)}finally{loading.value=false}})
function blur():void{finish(true)}
defineExpose({cancel:close})
onBeforeUnmount(()=>{closed=true;generation++;finish(true);cancelJob();resizeObserver?.disconnect();window.removeEventListener('blur',blur)})
</script>
<template><div class="edge-backdrop" @keydown="key" @pointerdown.self="close"><section class="edge-dialog" role="dialog" aria-modal="true" :aria-label="t('Refine Selection Edges')" data-testid="edge-refinement-dialog"><header><h2>{{t('Refine Selection Edges')}}</h2><button :disabled="applying" :aria-label="t('Close')" @click="close">×</button></header><p class="edge-limit">{{t('Experimental local color refinement. Low contrast, missing samples and changing colors limit results. Color decontamination is not available.')}}</p><div class="edge-workspace"><div class="edge-preview-column"><div class="edge-viewbar"><label>{{t('Preview background')}}<select v-model="background" :aria-label="t('Edge preview background')"><option v-for="mode in ['source','black','white','checker','gray']" :value="mode">{{t(mode==='source'?'Source image':mode==='checker'?'Checkerboard':mode==='gray'?'Gray':mode==='black'?'Black':'White')}}</option></select></label><label><input v-model="showConstraints" type="checkbox">{{t('Show constraints')}}</label><button @click="fit">{{t('Fit')}}</button><label>{{t('Zoom')}}<select v-model.number="scale" :aria-label="t('Edge workspace zoom')"><option :value="1">{{t('Fit')}}</option><option :value="2">200%</option><option :value="4">400%</option></select></label></div><div ref="stage" class="edge-stage" :class="{'edge-checker':background==='checker'}" :style="stageStyle"><canvas v-if="source" ref="canvas" tabindex="0" :aria-label="t('Edge constraint canvas')" :style="{width:`${fitWidth*scale}px`}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="cancelPointer" @lostpointercapture="cancelPointer"/><p v-else role="status">{{t('Loading edge source…')}}</p></div><p v-if="source" class="edge-source">{{t('Coarse source: {source}',{source:t(source.coarseSource==='selection'?'Selection':'Layer mask')})}} · {{t('Source dimensions {width} × {height} px',{width:source.width,height:source.height})}} · {{t('Thumbnail preview; output uses source pixels.')}}</p></div><aside><fieldset :disabled="busy"><legend>{{t('Hard round constraints')}}</legend><div class="edge-brushes"><button v-for="item in [{value:255,name:'Foreground constraint'},{value:0,name:'Background constraint'},{value:128,name:'Unknown constraint'}]" :aria-pressed="brush===item.value" @click="finish(true);brush=item.value as 0|128|255">{{t(item.name)}}</button></div><label>{{t('Constraint size')}}<input v-model.number="size" type="number" min="1" max="512" :aria-label="t('Constraint size')"></label><div class="edge-row"><button :disabled="!strokes.length" @click="finish(true);strokes.pop();invalidate()">{{t('Undo constraint')}}</button><button :disabled="!strokes.length" @click="finish(true);strokes=[];invalidate()">{{t('Clear constraints')}}</button></div><label>{{t('Boundary radius')}}<input v-model.number="boundaryRadius" type="number" min="1" max="40" :aria-label="t('Boundary radius')"></label><label>{{t('Sample radius')}}<input v-model.number="sampleRadius" type="number" min="1" max="64" :aria-label="t('Sample radius')"></label><label>{{t('Guided radius')}}<input v-model.number="guidedRadius" type="number" min="1" max="40" :aria-label="t('Guided radius')"></label><label><input v-model="regionEnabled" type="checkbox" :aria-label="t('Limit refinement region')">{{t('Limit refinement region')}}</label><div v-if="regionEnabled" class="edge-roi"><label v-for="axis in ['x','y','width','height'] as const">{{t(axis==='x'?'X':axis==='y'?'Y':axis==='width'?'Width':'Height')}}<input v-model.number="roi[axis]" type="number" :min="axis==='x'||axis==='y'?0:1" :aria-label="t('Refinement region {axis}',{axis})"></label></div><label>{{t('Output')}}<select v-model="output" :aria-label="t('Edge refinement output')"><option value="selection">{{t('Selection')}}</option><option value="mask">{{t('Layer mask')}}</option><option value="new-layer">{{t('New layer')}}</option></select></label></fieldset><p>{{t('Paint in source pixels. Constraints stay in this draft until Apply. Changes require a new Preview.')}}</p><p v-if="pending" role="status">{{t('Refining edge preview…')}}</p><p v-if="preview" role="status">{{t('{resolved} resolved; {fallback} preserved; {unknown} unknown pixels',{resolved:preview.report.resolvedPixels,fallback:preview.report.fallbackPixels,unknown:preview.report.unknownPixels})}}</p><p v-if="problem" role="alert">{{tm(problem)}}</p><button v-if="pending" @click="invalidate">{{t('Cancel preview')}}</button></aside></div><footer><button @click="close">{{t(applying?'Cancel applying edges':'Cancel')}}</button><button :disabled="busy||pending||loading" @click="makePreview">{{t('Preview edges')}}</button><button :disabled="!canApply" @click="apply">{{applying?t('Applying edges…'):t('Apply refined edges')}}</button></footer></section></div></template>
<style scoped>
.edge-backdrop{position:fixed;inset:0;background:#0009;z-index:85;display:grid;place-items:center;padding:12px}.edge-dialog{width:min(1120px,calc(100vw - 24px));max-height:calc(100vh - 24px);box-sizing:border-box;display:flex;flex-direction:column;background:#282828;border:1px solid #555;border-radius:10px;padding:16px;color:#ddd;box-shadow:0 16px 60px #0008;font-size:13px;overflow:auto}.edge-dialog header{display:flex;justify-content:space-between;align-items:center;gap:10px}.edge-dialog h2{font-size:18px;margin:0}.edge-limit{color:#d6bc7c;line-height:1.5}.edge-workspace{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:16px;min-height:0}.edge-preview-column{min-width:0;display:flex;flex-direction:column}.edge-viewbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}.edge-viewbar label{display:flex;gap:5px;align-items:center}.edge-stage{height: min(52vh,540px);min-height:180px;background:#171717;overflow:auto;display:flex;align-items:flex-start;justify-content:flex-start;border:1px solid #555}.edge-stage canvas{display:block;flex-shrink:0;touch-action:none;cursor:crosshair;outline:0;height:auto}.edge-checker{background:repeating-conic-gradient(#686868 0% 25%,#515151 0% 50%) 0 0/20px 20px}.edge-source{color:#aaa;font-size:12px}.edge-dialog aside{min-width:0}.edge-dialog fieldset{border:0;padding:0;margin:0;min-width:0}.edge-dialog legend{font-weight:600;margin-bottom:8px}.edge-dialog aside label{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:10px 0}.edge-dialog aside p{line-height:1.5;color:#bbb}.edge-dialog aside [role=alert]{color:#ffaba3;overflow-wrap:anywhere}.edge-brushes{display:flex;flex-wrap:wrap;gap:5px}.edge-brushes button{flex:1;min-width:75px}.edge-brushes button[aria-pressed=true]{background:#285882;border-color:#58a9ed}.edge-dialog input[type=number]{width:72px;box-sizing:border-box}.edge-dialog input,.edge-dialog select,.edge-dialog button{font:inherit;color:inherit;background:#202020;border:1px solid #555;border-radius:4px;padding:6px;min-width:0}.edge-dialog input,.edge-dialog select{height:30px;line-height:normal}.edge-dialog input[type=checkbox]{height:auto}.edge-dialog button{cursor:pointer}.edge-dialog button:disabled{opacity:.4;cursor:default}.edge-row{display:flex;gap:6px;flex-wrap:wrap}.edge-roi{display:grid;grid-template-columns:1fr 1fr;gap:0 8px}.edge-dialog footer{display:flex;justify-content:flex-end;gap:10px;padding-top:12px;border-top:1px solid #444;margin-top:10px;flex-wrap:wrap}.edge-dialog footer button:last-child{background:#1766a6}.edge-dialog select{max-width:170px}@media(max-width:700px){.edge-workspace{grid-template-columns:1fr}.edge-stage{height:32vh}.edge-dialog aside{overflow:visible}.edge-dialog{padding:12px}.edge-dialog aside label{margin:7px 0}.edge-dialog aside p{margin:8px 0}.edge-dialog select{max-width:155px}}
</style>
